      from: spec.fromAgentId ? ('agent:' + spec.fromAgentId) : (spec.from || 'user'),
      role: 'user',
      content: spec.content || '',
      connection: target.connection,
      model: target.model || null,
      contextRefs: spec.contextRefs || [],
      attachments: spec.attachments || [],
