      fromAgentId: spec.fromAgentId || null,
      requestMessageId: message.id,
      goal: String(spec.content || '').slice(0, 1000),
      status: 'queued',
      budget: effectiveRunBudget(spec.budget),
      meta: { sourceResponseId: spec.sourceResponseId || null },
