    const txt = ui.h('input', 'aiditor-ui-num-text', { type: 'text' })
    const inc = ui.h('button', 'aiditor-ui-num-step aiditor-ui-num-step-r', { type: 'button', text: '›' })
    const sfx = ui.h('span', 'aiditor-ui-num-suffix')
