    const el = ui.h('div', 'aiditor-ui-gradient')
    const barWrap = ui.h('div', 'aiditor-ui-gradient-barwrap')
    const checker = ui.h('div', 'aiditor-ui-gradient-checker')
    const bar     = ui.h('div', 'aiditor-ui-gradient-bar')
    const rail    = ui.h('div', 'aiditor-ui-gradient-rail')
